def split_csv(line):
    """
    Parse one line of CSV and return its fields as a list of strings, or None if malformed.
    """
    if line == "":
        return [""]

    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            i += 1
            field = ""
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote represents a single quote
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows: must be comma or end of line
                        if i < len(line) and line[i] != ',':
                            return None
                        if i < len(line):
                            i += 1  # Skip the comma
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None
            fields.append(field)
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields

